-- =============================================================================
-- Ultra Hero · 0048 · Conceito do programa
-- A página do programa ganha a parte conceitual na voz do próprio programa: ideia, para quem é (e para
-- quem não é), o que se conquista, como funciona, ritmo, o que precisa e cuidados. Fica na VERSÃO
-- (programas são versionados) e na TRADUÇÃO da versão, como título/resumo/descrição.
-- Sem tabela nova, sem política nova: as colunas herdam a RLS de program_versions/program_localizations.
-- Idempotente: "if not exists", constraints recriadas e os textos só preenchem conceito ainda nulo.
-- =============================================================================

-- Forma do jsonb (o app valida com zod; aqui a trava é estrutural e um pouco mais folgada):
-- { idea, for_who, not_for|null, outcomes[1..3], method[1..4]{title,text}, rhythm{sessions_per_week|null,
--   minutes_per_day|null, note|null}, needs[0..12], care }
create or replace function public.program_concept_valid(c jsonb)
returns boolean language plpgsql immutable parallel safe set search_path = public as $$
declare e jsonb;
begin
  if c is null then return true; end if;
  if jsonb_typeof(c) <> 'object' then return false; end if;
  -- textos obrigatórios
  if coalesce(jsonb_typeof(c -> 'idea'), '') <> 'string' or length(c ->> 'idea') not between 1 and 1000 then return false; end if;
  if coalesce(jsonb_typeof(c -> 'for_who'), '') <> 'string' or length(c ->> 'for_who') not between 1 and 600 then return false; end if;
  if coalesce(jsonb_typeof(c -> 'care'), '') <> 'string' or length(c ->> 'care') not between 1 and 800 then return false; end if;
  if coalesce(jsonb_typeof(c -> 'not_for'), 'null') not in ('string', 'null') then return false; end if;
  -- listas
  if coalesce(jsonb_typeof(c -> 'outcomes'), '') <> 'array' or jsonb_array_length(c -> 'outcomes') not between 1 and 3 then return false; end if;
  for e in select value from jsonb_array_elements(c -> 'outcomes') loop
    if jsonb_typeof(e) <> 'string' then return false; end if;
  end loop;
  if coalesce(jsonb_typeof(c -> 'method'), '') <> 'array' or jsonb_array_length(c -> 'method') not between 1 and 4 then return false; end if;
  for e in select value from jsonb_array_elements(c -> 'method') loop
    if jsonb_typeof(e) <> 'object' or coalesce(jsonb_typeof(e -> 'title'), '') <> 'string' or coalesce(jsonb_typeof(e -> 'text'), '') <> 'string' then return false; end if;
  end loop;
  if coalesce(jsonb_typeof(c -> 'needs'), '') <> 'array' or jsonb_array_length(c -> 'needs') > 12 then return false; end if;
  for e in select value from jsonb_array_elements(c -> 'needs') loop
    if jsonb_typeof(e) <> 'string' then return false; end if;
  end loop;
  -- ritmo
  if coalesce(jsonb_typeof(c -> 'rhythm'), '') <> 'object' then return false; end if;
  if coalesce(jsonb_typeof(c -> 'rhythm' -> 'sessions_per_week'), 'null') not in ('number', 'null')
     or coalesce(jsonb_typeof(c -> 'rhythm' -> 'minutes_per_day'), 'null') not in ('number', 'null')
     or coalesce(jsonb_typeof(c -> 'rhythm' -> 'note'), 'null') not in ('string', 'null') then return false; end if;
  return true;
end $$;
-- usada só nas constraints (quem escreve é o admin, autenticado); o visitante não precisa executá-la
revoke execute on function public.program_concept_valid(jsonb) from public, anon;
grant execute on function public.program_concept_valid(jsonb) to authenticated, service_role;

alter table public.program_versions add column if not exists concept jsonb;
alter table public.program_localizations add column if not exists concept jsonb;

alter table public.program_versions drop constraint if exists program_versions_concept_shape;
alter table public.program_versions add constraint program_versions_concept_shape check (public.program_concept_valid(concept));
alter table public.program_localizations drop constraint if exists program_localizations_concept_shape;
alter table public.program_localizations add constraint program_localizations_concept_shape check (public.program_concept_valid(concept));

comment on column public.program_versions.concept is 'Conceito do programa (0048): idea, for_who, not_for, outcomes[], method[{title,text}], rhythm{sessions_per_week,minutes_per_day,note}, needs[], care.';
comment on column public.program_localizations.concept is 'Conceito traduzido (mesma forma de program_versions.concept); vale quando a tradução está publicada.';

-- Nova versão copia também o conceito (mesma função da 0003; só entra a coluna concept).
create or replace function public.admin_create_program_version(p_program uuid, p_copy_from uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_no int; v_id uuid; src public.program_versions%rowtype;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select coalesce(max(version_no), 0) + 1 into v_no from public.program_versions where program_id = p_program;
  if p_copy_from is not null then
    select * into src from public.program_versions where id = p_copy_from and program_id = p_program;
  end if;
  insert into public.program_versions (program_id, version_no, title, summary, description, concept, source_locale, estimated_weeks, certificate_fields, created_by)
  values (p_program, v_no, coalesce(src.title, 'Nova versão'), src.summary, src.description, src.concept, coalesce(src.source_locale, 'pt-BR'), src.estimated_weeks,
          coalesce(src.certificate_fields, '["display_name","program_title","completed_at","version"]'::jsonb), auth.uid())
  returning id into v_id;
  if src.id is not null then
    insert into public.program_items (version_id, content_id, position, section, is_required)
    select v_id, content_id, position, section, is_required from public.program_items where version_id = src.id;
  end if;
  perform public.audit_log('program.version_create', 'program', p_program::text, null, jsonb_build_object('version_id', v_id, 'version_no', v_no, 'copied_from', p_copy_from));
  return v_id;
end $$;
revoke execute on function public.admin_create_program_version(uuid, uuid) from public, anon;
grant execute on function public.admin_create_program_version(uuid, uuid) to authenticated, service_role;

-- ---------------------------------------------------------------- textos (dados de demonstração)
-- Conceito em pt-BR para os 24 programas do seed (0008 e 0035) e em en/es para os 16 que já têm tradução.
-- Chave = slug do programa + versão ATUAL (não depende do herói: programa arquivado ou de herói oculto
-- também recebe). Só preenche onde o conceito ainda é nulo: reexecutar não sobrescreve edição do admin.
drop table if exists seed_concept;
create temporary table seed_concept (slug text, locale text, concept jsonb);
insert into seed_concept (slug, locale, concept) values
  ('manhas-com-intencao', 'pt-BR', $c${"idea":"Eu não sou um desafio de produtividade: sou um começo de dia que cabe em dez minutos. Água, luz, um pouco de movimento, uma respiração e uma intenção — antes de abrir o celular. E, como toda manhã começa na noite anterior, também cuido de como você vai dormir.","for_who":"Para quem acorda já correndo, pega o celular antes de levantar e quer uma manhã mais calma sem precisar acordar muito mais cedo.","not_for":"Não é para quem procura uma rotina de alta performance com horários rígidos ou um plano de treino.","outcomes":["Um ritual matinal de cerca de 10 minutos que você consegue repetir","Uma respiração curta (4-7-8) para usar nas transições do dia","Uma noite preparada para facilitar a manhã seguinte"],"method":[{"title":"Monte o ritual","text":"Comece pelo vídeo do ritual de 10 minutos: água, luz natural, movimento leve e uma intenção para o dia."},{"title":"Aprenda a desacelerar","text":"Pratique a respiração 4-7-8 ao acordar ou antes de uma tarefa difícil."},{"title":"Prepare a noite","text":"Use o guia da rotina noturna e os ajustes de higiene do sono para reduzir decisões à noite."},{"title":"Repita e revise","text":"Repita o ritual pelos 7 dias e, se quiser, feche a semana com o checklist de autocuidado."}],"rhythm":{"sessions_per_week":7,"minutes_per_day":10,"note":"Todas as manhãs, durante uma semana."},"needs":["Um copo de água","Um lugar com luz natural"],"care":"Conteúdo educativo; não substitui orientação profissional. Se a falta de sono ou o cansaço persistirem, procure um profissional de saúde."}$c$::jsonb),
  ('reset-de-habitos-em-21-dias', 'pt-BR', $c${"idea":"Eu não vou te dar uma lista nova de hábitos. Vou te ajudar a olhar para os que você já tem, escolher poucos e sustentá-los por três semanas. Três prioridades por dia, uma sequência que ajuda sem virar cobrança e pausas curtas para respirar.","for_who":"Para quem começa muitos hábitos e larga no meio, sente o dia fragmentado e quer um sistema simples para manter o que importa.","not_for":"Não é para quem quer mudar tudo de uma vez ou busca um método de produtividade cheio de ferramentas.","outcomes":["Clareza sobre três prioridades por dia","Uma forma saudável de usar sequências (streaks) sem culpa no dia ruim","Uma revisão curta para decidir o que manter na semana seguinte"],"method":[{"title":"Escolha o essencial","text":"Organize o dia em blocos de foco com no máximo três prioridades."},{"title":"Entenda as sequências","text":"Veja quando contar dias seguidos ajuda e quando atrapalha, e defina o mínimo para os dias difíceis."},{"title":"Respire nas transições","text":"Use a respiração 4-7-8 entre um bloco e outro e antes de dormir."},{"title":"Revise a cada semana","text":"Ao fim de cada semana, faça a revisão de 15 minutos e, se fizer sentido, o experimento de menos telas à noite."}],"rhythm":{"sessions_per_week":5,"minutes_per_day":15,"note":"Três semanas; a revisão acontece uma vez por semana."},"needs":["Papel e caneta ou um app de notas"],"care":"Conteúdo educativo; não substitui orientação profissional."}$c$::jsonb),
  ('base-de-forca-4-semanas', 'pt-BR', $c${"idea":"Força não começa no peso: começa no movimento bem feito. Em quatro semanas eu te ensino os padrões que sustentam qualquer treino — agachar, empurrar e puxar — com técnica primeiro e progressão segura depois. Sem academia e sem pressa.","for_who":"Para iniciantes ou para quem está voltando a treinar e quer aprender os movimentos básicos com segurança, em casa.","not_for":"Não é para quem já treina força com regularidade e busca cargas altas ou periodização avançada.","outcomes":["Técnica de agachamento ajustada, sem os erros mais comuns","Um treino de corpo inteiro com o peso do corpo que você faz sozinho","Os três padrões básicos (agachar, empurrar, puxar) praticados com progressão"],"method":[{"title":"Técnica primeiro","text":"Comece pelo vídeo dos 5 erros comuns no agachamento e ajuste joelhos, calcanhares e tronco."},{"title":"Corpo inteiro","text":"Faça o treino funcional iniciante de 25 minutos, sem equipamento, duas ou três vezes por semana."},{"title":"Os três padrões","text":"Avance para o treino de força básica e mantenha a técnica antes de aumentar repetições."},{"title":"Vá além (opcional)","text":"Inclua o core de 12 minutos e, quando estiver confortável, as progressões com elástico."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":30,"note":"Deixe pelo menos um dia de descanso entre os treinos."},"needs":["Um espaço livre no chão","Tapete ou colchonete","Elástico de resistência (opcional)"],"care":"Conteúdo educativo; não substitui orientação profissional. Pare se sentir dor e procure um profissional habilitado; se você tem alguma condição de saúde, converse com seu médico antes de começar."}$c$::jsonb),
  ('do-sofa-aos-5-km', 'pt-BR', $c${"idea":"Eu não tenho pressa de te ver correndo. Começamos alternando caminhada e corrida leve e aumentamos aos poucos, até você completar 5 km com conforto. Tênis adequado, quadril solto e aquecimento fazem parte do caminho tanto quanto a corrida.","for_who":"Para quem está saindo do sedentarismo, nunca correu ou parou há muito tempo e quer chegar aos 5 km sem se machucar.","not_for":"Não é para quem já corre 5 km e quer melhorar o tempo ou treinar para provas.","outcomes":["Completar 5 km alternando ou só correndo, no seu ritmo","Uma rotina de aquecimento e mobilidade antes de sair","Critérios práticos para escolher um tênis confortável"],"method":[{"title":"Prepare-se","text":"Leia o guia de como escolher o tênis e faça a mobilidade de quadril de 8 minutos."},{"title":"Caminhe e corra","text":"Comece pela semana 1 da caminhada-corrida, três vezes por semana, com dias de descanso entre elas."},{"title":"Aumente aos poucos","text":"A cada semana, troque um pouco de caminhada por corrida leve, só se a semana anterior foi confortável."},{"title":"Consolide","text":"Use o aquecimento de 5 minutos antes de cada saída e, no fim, experimente o intervalado leve."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":30,"note":"Seis semanas; repita uma semana sempre que precisar."},"needs":["Tênis de corrida confortável","Roupa leve","Água"],"care":"Conteúdo educativo; não substitui orientação profissional. Pare se sentir dor e procure um profissional habilitado; se você tem alguma condição de saúde, converse com seu médico antes de começar. Se sentir falta de ar fora do normal, tontura ou dor no peito, pare imediatamente."}$c$::jsonb),
  ('fundamentos-da-nutricao-real', 'pt-BR', $c${"idea":"Eu não sou uma dieta. Sou um jeito de escolher melhor no dia a dia: montar o prato sem balança, entender o rótulo pelo que importa e fazer uma lista de compras que evita impulso e desperdício. Nutrição real é a que cabe na sua rotina.","for_who":"Para quem está cansado de dietas da moda e quer entender o básico para fazer escolhas práticas no mercado e no prato.","not_for":"Não é para quem procura um cardápio individual, contagem de calorias ou plano para perder peso.","outcomes":["Montar um prato equilibrado usando a mão como medida","Ler um rótulo começando pela porção e pela lista de ingredientes","Uma lista de compras que reduz desperdício e decisões por impulso"],"method":[{"title":"O prato","text":"Aprenda o método da mão para dividir o prato entre vegetais, proteína, carboidrato e gordura."},{"title":"O rótulo","text":"Use o guia das 5 coisas para olhar primeiro na embalagem e o que pode ignorar."},{"title":"A lista","text":"Monte sua lista de compras a partir das refeições que você já costuma fazer."},{"title":"Vá além (opcional)","text":"Explore fibras no dia a dia e por que distribuir proteína ao longo das refeições."}],"rhythm":{"sessions_per_week":null,"minutes_per_day":10,"note":"Duas semanas; uma etapa por vez, no seu ritmo."},"needs":[],"care":"Conteúdo educativo; não substitui orientação de nutricionista nem de médico. Não traz metas individuais de calorias ou de peso."}$c$::jsonb),
  ('hidratacao-e-energia', 'pt-BR', $c${"idea":"Energia no dia a dia começa em coisas simples: beber água prestando atenção aos sinais do corpo e não sair de casa sem comer. Em uma semana eu te ajudo a ajustar esses dois hábitos sem regras fixas nem garrafas gigantes.","for_who":"Para quem esquece de beber água, pula o café da manhã na correria e sente a energia cair ao longo do dia.","not_for":"Não é para quem precisa de orientação de hidratação por condição de saúde ou para provas esportivas longas.","outcomes":["Reconhecer sinais de sede e criar lembretes que funcionam para você","Três ideias de café da manhã que ficam prontas em 5 minutos","Um plano simples para não ficar sem refeição na semana"],"method":[{"title":"Água com contexto","text":"Leia sobre hidratação: sinais do corpo, rotina e clima valem mais que uma meta fixa."},{"title":"Café da manhã rápido","text":"Escolha uma das três ideias de 5 minutos e repita durante a semana."},{"title":"Planeje (opcional)","text":"Use o método de 30 minutos para planejar refeições e, se treina, veja o básico do pré e pós-treino."}],"rhythm":{"sessions_per_week":null,"minutes_per_day":5,"note":"Uma semana de pequenos ajustes diários."},"needs":["Uma garrafa ou copo para deixar à vista"],"care":"Conteúdo educativo; não substitui orientação de nutricionista nem de médico. Não traz metas individuais de calorias ou de peso. Pessoas com restrição de líquidos devem seguir a orientação do seu médico."}$c$::jsonb),
  ('cozinha-de-base-preparos-essenciais', 'pt-BR', $c${"idea":"Cozinhar com confiança vem de dominar poucas bases: uma faca afiada, um molho coringa, um arroz que fica soltinho e um bowl completo. Eu te ensino essas peças para você combinar do seu jeito na semana inteira.","for_who":"Para quem cozinha pouco ou sempre as mesmas coisas e quer técnicas de base para ganhar segurança e velocidade.","not_for":"Não é para quem procura alta gastronomia ou receitas elaboradas de ocasião.","outcomes":["Facas afiadas e cuidadas, com mais segurança no corte","Arroz integral soltinho e um molho de ervas em 5 minutos","Um bowl completo montado com as bases que você aprendeu"],"method":[{"title":"Ferramenta","text":"Comece aprendendo a afiar e cuidar das facas."},{"title":"Bases","text":"Faça o molho de ervas e o arroz integral; os dois rendem e duram na geladeira."},{"title":"Monte o prato","text":"Junte tudo no bowl de frango grelhado com legumes assados."},{"title":"Vá além (opcional)","text":"Pratique o mise en place e a panqueca de aveia e banana para o café da manhã."}],"rhythm":{"sessions_per_week":2,"minutes_per_day":40,"note":"Duas semanas; cozinhe uma ou duas receitas por semana."},"needs":["Faca de chef","Tábua","Panela com tampa","Assadeira","Frigideira"],"care":"Receitas demonstrativas com quantidades ilustrativas. Confira os alergênicos de cada receita (a panqueca leva ovo e aveia, que pode conter glúten). Cuidado com facas e superfícies quentes."}$c$::jsonb),
  ('marmitas-da-semana', 'pt-BR', $c${"idea":"Uma tarde de cozinha pode resolver cinco dias. Eu te mostro preparos simples que rendem, congelam bem e montam marmitas equilibradas — começando por uma omelete de forno e um arroz integral que acompanha tudo.","for_who":"Para quem almoça fora do jeito que dá, gasta com delivery na correria e quer ter refeição pronta em casa.","not_for":"Não é para quem quer cozinhar todos os dias ou procura receitas para ocasiões especiais.","outcomes":["Uma omelete de forno que vira oito porções congeladas","Arroz integral pronto para a semana","Um método para montar, congelar e aquecer marmitas"],"method":[{"title":"Base da semana","text":"Prepare a omelete de forno e o arroz integral no mesmo dia."},{"title":"Porcione","text":"Divida em potes, etiquete com a data e congele o que não for comer em poucos dias."},{"title":"Varie (opcional)","text":"Inclua a sopa de grão-de-bico, a marmita de carne com abóbora ou o salmão com batata-doce."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Uma sessão de preparo de cerca de 1h30 por semana."},"needs":["Assadeira","Panela com tampa","Potes com tampa que vão ao freezer","Etiquetas ou fita"],"care":"Receitas demonstrativas. Alergênicos: a omelete leva ovo e leite; o salmão é peixe. Resfrie antes de congelar, aqueça bem antes de comer e siga as boas práticas de conservação."}$c$::jsonb),
  ('noites-que-descansam', 'pt-BR', $c${"idea":"Eu não vou te dar regras rígidas de sono. Vou te propor ajustes pequenos — luz, telas, respiração e um ritual curto antes de deitar — para você testar um de cada vez e manter os que funcionarem. Dormir melhor é uma soma de detalhes.","for_who":"Para quem demora a desligar à noite, fica nas telas até tarde ou acorda cansado e quer experimentar mudanças simples.","not_for":"Não é tratamento para insônia ou outros distúrbios do sono.","outcomes":["Oito ajustes de higiene do sono testados na sua rotina","Um ritual curto de alongamento e respiração antes de deitar","Um horário para desligar as telas que você consegue manter"],"method":[{"title":"Ajuste o ambiente","text":"Comece pelos 8 ajustes de higiene do sono: luz, temperatura, cafeína e telas."},{"title":"Monte a rotina noturna","text":"Use o guia da rotina noturna para reduzir decisões e preparar a manhã."},{"title":"Desacelere o corpo","text":"Faça o alongamento leve de 12 minutos e a respiração 4-7-8 antes de deitar."},{"title":"Experimente e mantenha","text":"Teste um ajuste por vez, repita os que funcionarem e, se quiser, faça o experimento de 7 dias sem telas."}],"rhythm":{"sessions_per_week":7,"minutes_per_day":15,"note":"Todas as noites, por duas semanas."},"needs":["Tapete ou colchonete para o alongamento"],"care":"Conteúdo educativo; não substitui orientação profissional. Se a dificuldade para dormir durar semanas ou afetar o seu dia, procure um profissional de saúde."}$c$::jsonb),
  ('autocuidado-em-pequenas-doses', 'pt-BR', $c${"idea":"Autocuidado não precisa ser uma lista impossível. Eu caibo em poucos minutos: um checklist leve, um ritual de manhã, uma pausa de foco e um alongamento no fim do dia. Pequenas doses, repetidas, contam mais do que um grande dia de folga.","for_who":"Para quem vive dias corridos, sempre deixa o próprio cuidado para depois e quer gestos curtos que caibam na agenda.","not_for":"Não é para quem busca acompanhamento emocional ou psicológico.","outcomes":["Um checklist semanal de sono, movimento, comida e descanso","Um ritual matinal curto que você repete sem esforço","Um jeito de usar sequências a seu favor, sem culpa"],"method":[{"title":"Olhe para a semana","text":"Comece pelo checklist semanal de autocuidado e escolha um ponto para cuidar."},{"title":"Comece o dia","text":"Inclua o ritual matinal de 10 minutos nas manhãs que der."},{"title":"Mantenha sem cobrança","text":"Entenda quando a sequência ajuda e organize o dia em três prioridades."},{"title":"Feche o dia (opcional)","text":"Use o alongamento antes de dormir e a revisão semanal de 15 minutos."}],"rhythm":{"sessions_per_week":5,"minutes_per_day":10,"note":"Duas semanas; um gesto curto por dia."},"needs":[],"care":"Conteúdo educativo; não substitui orientação profissional. Se estiver passando por um momento difícil, procure apoio de um profissional de saúde mental."}$c$::jsonb),
  ('semana-sob-controle', 'pt-BR', $c${"idea":"Eu sou um sistema simples de planejamento: quinze minutos de revisão no domingo, três prioridades por dia e folga no calendário para o imprevisto. O objetivo não é fazer mais — é terminar a semana sabendo o que importou.","for_who":"Para quem sente a semana escapar, vive apagando incêndio e quer um ritual curto de planejamento que funcione na vida real.","not_for":"Não é para quem procura um software de gestão de projetos ou uma metodologia corporativa.","outcomes":["Uma revisão semanal de 15 minutos que vira hábito","Dias organizados em blocos de foco com três prioridades","Espaço no calendário para você e para o imprevisto"],"method":[{"title":"Revise","text":"Faça a revisão semanal: olhe para trás, escolha o que manter e planeje com folga."},{"title":"Priorize o dia","text":"Organize cada dia em blocos de foco com no máximo três prioridades."},{"title":"Sustente","text":"Use sequências como apoio, não como cobrança, e o checklist para não esquecer de você."},{"title":"Ajuste (opcional)","text":"Experimente menos telas à noite e um ritual matinal para começar o dia com calma."}],"rhythm":{"sessions_per_week":5,"minutes_per_day":10,"note":"A revisão leva 15 minutos uma vez por semana."},"needs":["Agenda ou calendário","Papel e caneta ou um app de notas"],"care":"Conteúdo educativo; não substitui orientação profissional."}$c$::jsonb),
  ('foco-sem-telas', 'pt-BR', $c${"idea":"Atenção é treinável. Eu proponho um experimento guiado: menos telas à noite, respiração nas transições e blocos de foco durante o dia. Sem radicalismo e sem culpa — você testa, observa e fica com o que funcionar.","for_who":"Para quem pega o celular sem perceber, tem dificuldade de se concentrar e fica nas telas até a hora de dormir.","not_for":"Não é para quem procura tratamento para dependência digital ou dificuldades de atenção diagnosticadas.","outcomes":["Um horário à noite para desligar as telas que você consegue manter","Blocos de foco com três prioridades durante o dia","Uma respiração curta para voltar ao foco nas transições"],"method":[{"title":"Faça o experimento","text":"Siga o experimento guiado de 7 dias para reduzir telas à noite."},{"title":"Respire entre tarefas","text":"Use a respiração 4-7-8 ao trocar de atividade e antes de dormir."},{"title":"Proteja o foco","text":"Organize o dia em blocos com três prioridades e ajuste a higiene do sono."},{"title":"Vá além (opcional)","text":"Monte a rotina noturna e faça a revisão semanal para ver o que mudou."}],"rhythm":{"sessions_per_week":7,"minutes_per_day":10,"note":"Duas semanas; o experimento de telas dura 7 dias."},"needs":[],"care":"Conteúdo educativo; não substitui orientação profissional."}$c$::jsonb),
  ('forca-em-casa-com-elastico', 'pt-BR', $c${"idea":"Dá para ficar mais forte sem academia. Comigo a ordem é clara: técnica primeiro, peso do corpo depois e só então o elástico de resistência. Quatro semanas para progredir em casa com segurança.","for_who":"Para quem treina em casa, já conhece o básico ou está começando, e quer evoluir na força com pouco equipamento.","not_for":"Não é para quem busca treino com cargas altas ou preparação para competições.","outcomes":["Agachamento com técnica ajustada","Domínio de um treino de corpo inteiro com o peso do corpo","Progressões com elástico para continuar evoluindo em casa"],"method":[{"title":"Ajuste a técnica","text":"Corrija os 5 erros comuns do agachamento antes de qualquer carga."},{"title":"Peso do corpo","text":"Faça o treino funcional de corpo inteiro até ele ficar confortável."},{"title":"Acrescente o elástico","text":"Siga o treino de força com elástico e inclua o core de 12 minutos."},{"title":"Vá além (opcional)","text":"Pratique os três padrões básicos e a mobilidade de quadril nos dias leves."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":30,"note":"Quatro semanas, com um dia de descanso entre os treinos."},"needs":["Elástico de resistência","Tapete ou colchonete","Um espaço livre no chão"],"care":"Conteúdo educativo; não substitui orientação profissional. Pare se sentir dor e procure um profissional habilitado; se você tem alguma condição de saúde, converse com seu médico antes de começar. Confira o elástico antes de usar e descarte se estiver rachado ou ressecado."}$c$::jsonb),
  ('core-e-postura-em-3-semanas', 'pt-BR', $c${"idea":"Postura não é ficar duro: é ter estabilidade e mobilidade para se mexer bem. Eu junto blocos curtos de core, mobilidade de quadril e técnica para sustentar o corpo no treino e no dia a dia — em sessões que cabem em qualquer intervalo.","for_who":"Para quem passa muito tempo sentado, sente o corpo travado e quer uma base de estabilidade para treinar e viver melhor.","not_for":"Não é tratamento para dor nas costas ou reabilitação de lesão.","outcomes":["Um bloco de core de 12 minutos que você faz em qualquer lugar","Mais mobilidade de quadril para quem passa o dia sentado","Técnica para manter a postura nos movimentos de força"],"method":[{"title":"Estabilidade","text":"Comece pelo core de 12 minutos, priorizando o controle do movimento."},{"title":"Técnica","text":"Ajuste o agachamento com o vídeo dos 5 erros comuns."},{"title":"Mobilidade","text":"Inclua a mobilidade de quadril de 8 minutos nos dias sem treino."},{"title":"Integre","text":"Use o treino funcional de corpo inteiro e, se quiser, avance para força básica ou elástico."}],"rhythm":{"sessions_per_week":4,"minutes_per_day":15,"note":"Três semanas de sessões curtas."},"needs":["Tapete ou colchonete"],"care":"Conteúdo educativo; não substitui orientação profissional. Pare se sentir dor e procure um profissional habilitado; se você tem alguma condição de saúde, converse com seu médico antes de começar."}$c$::jsonb),
  ('mobilidade-para-correr-melhor', 'pt-BR', $c${"idea":"Correr bem começa antes da corrida. Eu te ajudo a preparar o corpo — aquecimento, quadril solto, core e um bom tênis — para você correr sem travar e voltar com vontade de repetir.","for_who":"Para quem já caminha ou corre e sente o quadril, os tornozelos ou o corpo travados antes ou depois de correr.","not_for":"Não é tratamento para lesões nem um plano de treino de corrida.","outcomes":["Um aquecimento de 5 minutos antes de cada corrida","Uma sequência de mobilidade de quadril para os dias sentado","Um core mais estável para correr com mais controle"],"method":[{"title":"Aqueça","text":"Faça o aquecimento de 5 minutos para tornozelos, quadril e respiração antes de sair."},{"title":"Solte o quadril","text":"Use a mobilidade de quadril de 8 minutos depois da corrida ou ao fim do dia."},{"title":"Fortaleça a base","text":"Ajuste a técnica do agachamento e inclua o core de 12 minutos duas vezes por semana."},{"title":"Escolha bem (opcional)","text":"Revise seu tênis com o guia e volte à caminhada-corrida se estiver recomeçando."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":15,"note":"Duas semanas, junto com as suas corridas."},"needs":["Tênis de corrida","Tapete ou colchonete"],"care":"Conteúdo educativo; não substitui orientação profissional. Pare se sentir dor e procure um profissional habilitado; se você tem alguma condição de saúde, converse com seu médico antes de começar."}$c$::jsonb),
  ('primeiro-intervalado', 'pt-BR', $c${"idea":"Intervalado não precisa ser sofrimento. Eu sou a ponte entre a caminhada-corrida e os primeiros tiros curtos: aquecimento bem feito, base consolidada e recuperação generosa entre os esforços. Você termina querendo mais, não exausto.","for_who":"Para quem já caminha-corre com conforto e quer experimentar, com cuidado, os primeiros treinos intervalados.","not_for":"Não é para quem está começando do zero (comece por Do Sofá aos 5 km) nem para quem busca treino de alta intensidade.","outcomes":["Uma base de caminhada-corrida consolidada","Os primeiros treinos intervalados leves, com recuperação generosa","Uma rotina de aquecimento e mobilidade antes e depois"],"method":[{"title":"Aqueça sempre","text":"Faça o aquecimento de 5 minutos antes de toda saída."},{"title":"Consolide a base","text":"Repita a caminhada-corrida até ela ficar confortável."},{"title":"Primeiros tiros","text":"Siga o intervalado leve: esforços curtos e recuperação generosa, uma vez por semana."},{"title":"Recupere","text":"Solte o quadril depois de correr e, se quiser, complemente com core e treino funcional."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":25,"note":"Quatro semanas; no máximo um intervalado por semana."},"needs":["Tênis de corrida","Relógio ou cronômetro no celular","Água"],"care":"Conteúdo educativo; não substitui orientação profissional. Pare se sentir dor e procure um profissional habilitado; se você tem alguma condição de saúde, converse com seu médico antes de começar. Se sentir falta de ar fora do normal, tontura ou dor no peito, pare imediatamente."}$c$::jsonb),
  ('supermercado-sem-misterio', 'pt-BR', $c${"idea":"As melhores escolhas começam antes do prato: na lista e no carrinho. Eu te ajudo a montar uma lista que evita desperdício, ler o rótulo pelo que importa e transformar as compras em pratos equilibrados — sem demonizar alimento nenhum.","for_who":"Para quem se perde no mercado, compra por impulso ou não sabe por onde começar a ler um rótulo.","not_for":"Não é para quem precisa de uma dieta individual ou de orientação para alergias e doenças.","outcomes":["Uma lista de compras inteligente baseada na sua semana","Leitura de rótulos começando pela porção e pelos ingredientes","Pratos equilibrados montados com o que você comprou"],"method":[{"title":"Planeje a lista","text":"Monte a lista a partir das refeições da semana e do que já tem em casa."},{"title":"Leia o rótulo","text":"Veja as 5 coisas para olhar primeiro e o que pode ignorar na embalagem."},{"title":"Do carrinho ao prato","text":"Use o método da mão e inclua fontes simples de fibras."},{"title":"Vá além (opcional)","text":"Planeje refeições em 30 minutos e tenha lanches práticos à mão."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Cerca de 30 minutos por semana, acompanhando suas idas ao mercado."},"needs":["Papel ou app de notas para a lista"],"care":"Conteúdo educativo; não substitui orientação de nutricionista nem de médico. Não traz metas individuais de calorias ou de peso. Se você tem alergia ou intolerância alimentar, confira sempre a lista de ingredientes."}$c$::jsonb),
  ('lanches-e-proteina-no-dia-a-dia', 'pt-BR', $c${"idea":"A fome da tarde não é falta de força de vontade: muitas vezes é falta de plano. Eu reúno ideias de lanches, cafés da manhã rápidos e conceitos gerais sobre distribuir proteína ao longo do dia — sem metas individuais e sem complicação.","for_who":"Para quem chega faminto ao fim da tarde, belisca o que encontra e quer combinações práticas para comer melhor entre as refeições.","not_for":"Não é para quem precisa de metas individuais de proteína ou de um plano alimentar.","outcomes":["Combinações de lanche práticas para a tarde","Três cafés da manhã de 5 minutos","Entendimento geral de por que distribuir proteína nas refeições"],"method":[{"title":"Lanches","text":"Escolha duas ou três combinações de lanche e deixe os ingredientes à mão."},{"title":"Proteína no dia","text":"Entenda os conceitos gerais de distribuir proteína entre as refeições."},{"title":"Monte o prato","text":"Use o método da mão e um café da manhã rápido para começar bem."},{"title":"Vá além (opcional)","text":"Veja o básico do pré e pós-treino, fibras e hidratação."}],"rhythm":{"sessions_per_week":null,"minutes_per_day":10,"note":"Duas semanas; um ajuste por vez."},"needs":[],"care":"Conteúdo educativo; não substitui orientação de nutricionista nem de médico. Não traz metas individuais de calorias ou de peso. Se você tem alergia ou intolerância alimentar, adapte as combinações."}$c$::jsonb),
  ('planejamento-de-refeicoes-em-4-semanas', 'pt-BR', $c${"idea":"Trinta minutos por semana para decidir, comprar e preparar. Eu sou um método de planejamento que cabe na rotina: cardápio simples, lista de compras, café da manhã resolvido, água por perto e pratos equilibrados sem balança. Em quatro semanas, vira hábito.","for_who":"Para quem decide o que comer na última hora, desperdiça comida e quer uma rotina de planejamento que dure.","not_for":"Não é para quem precisa de um cardápio prescrito ou de dieta para condição de saúde.","outcomes":["Um ritual semanal de 30 minutos para planejar as refeições","Lista de compras alinhada ao cardápio, com menos desperdício","Café da manhã e hidratação resolvidos na rotina"],"method":[{"title":"Decida","text":"Use o método de 30 minutos para escolher as refeições da semana."},{"title":"Compre","text":"Transforme o cardápio em lista de compras inteligente."},{"title":"Resolva o básico","text":"Escolha cafés da manhã de 5 minutos e ajuste a hidratação aos sinais do corpo."},{"title":"Repita e refine","text":"Repita o ciclo por quatro semanas; se quiser, use o método da mão e a leitura de rótulos."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Cerca de 30 minutos de planejamento por semana."},"needs":["Papel ou app de notas","Potes para guardar preparos"],"care":"Conteúdo educativo; não substitui orientação de nutricionista nem de médico. Não traz metas individuais de calorias ou de peso."}$c$::jsonb),
  ('energia-para-treinar', 'pt-BR', $c${"idea":"Treinar bem também depende do que acontece fora do treino. Eu reúno princípios gerais para ter energia: beber água de acordo com o corpo, comer bem antes e depois e distribuir proteína ao longo do dia — de forma educativa, sem exagero.","for_who":"Para quem começou a treinar e quer entender o básico de hidratação e alimentação ao redor do treino.","not_for":"Não é para atletas que precisam de estratégia nutricional individual ou de suplementação.","outcomes":["Princípios gerais de hidratação no dia a dia e no treino","Ideias práticas para comer antes e depois de treinar","Entendimento geral da distribuição de proteína no dia"],"method":[{"title":"Hidrate-se","text":"Leia sobre hidratação e observe os sinais do corpo nos dias de treino."},{"title":"Antes e depois","text":"Veja o básico do pré e pós-treino, sem exageros."},{"title":"Café da manhã","text":"Escolha uma das ideias de 5 minutos para os dias de treino cedo."},{"title":"Proteína no dia","text":"Entenda por que distribuir proteína e, se quiser, explore lanches e fibras."}],"rhythm":{"sessions_per_week":null,"minutes_per_day":10,"note":"Duas semanas, acompanhando seus dias de treino."},"needs":[],"care":"Conteúdo educativo; não substitui orientação de nutricionista nem de médico. Não traz metas individuais de calorias ou de peso. Não é recomendação de suplementos."}$c$::jsonb),
  ('tecnicas-de-faca-e-mise-en-place', 'pt-BR', $c${"idea":"Toda cozinha rápida tem a mesma base: facas afiadas e bancada organizada antes de ligar o fogo. Eu te ensino esses dois hábitos e os aplico num molho coringa e num bowl completo, para você sentir a diferença no primeiro jantar.","for_who":"Para quem demora na cozinha, se enrola no meio da receita ou tem receio de usar a faca.","not_for":"Não é um curso profissional de cozinha.","outcomes":["Facas afiadas, bem cuidadas e mais seguras","O hábito do mise en place antes de cozinhar","Um molho de ervas e um bowl completo no repertório"],"method":[{"title":"Cuide da faca","text":"Aprenda a afiar e manter as facas — uma faca afiada é mais segura."},{"title":"Organize a bancada","text":"Pratique o mise en place: tudo cortado e separado antes do fogo."},{"title":"Aplique","text":"Faça o molho de ervas e monte o bowl de frango com legumes assados."},{"title":"Vá além (opcional)","text":"Use as mesmas técnicas no salmão ao forno e no arroz integral."}],"rhythm":{"sessions_per_week":2,"minutes_per_day":30,"note":"Duas semanas; cozinhe uma ou duas vezes por semana."},"needs":["Faca de chef","Tábua","Pedra ou chaira para afiar","Tigelas pequenas"],"care":"Receitas demonstrativas; confira os alergênicos (o salmão é peixe). Corte sempre com a ponta dos dedos recolhida e mantenha as facas longe da borda da bancada."}$c$::jsonb),
  ('cozinha-rapida-do-dia-a-dia', 'pt-BR', $c${"idea":"Comida boa no dia a dia não precisa de muitos passos. Eu reúno preparos práticos do café da manhã ao jantar de forno — panqueca de três ingredientes, molho de ervas, bowl grelhado e salmão — para você ter sabor sem passar a noite na cozinha.","for_who":"Para quem chega cansado em casa e quer receitas rápidas e saborosas para variar a semana.","not_for":"Não é para quem procura receitas para ocasiões especiais ou técnicas avançadas.","outcomes":["Um café da manhã de três ingredientes em poucos minutos","Um molho coringa que muda qualquer prato","Dois jantares completos: bowl grelhado e salmão ao forno"],"method":[{"title":"Café da manhã","text":"Comece pela panqueca de aveia e banana."},{"title":"O coringa","text":"Prepare o molho de ervas; ele dura dias na geladeira."},{"title":"Jantares","text":"Faça o bowl de frango grelhado e o salmão ao forno com batata-doce."},{"title":"Agilize","text":"Mantenha as facas afiadas e, se quiser, adiante a semana com a omelete de forno e o mise en place."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":30,"note":"Duas semanas; escolha os dias que quiser cozinhar."},"needs":["Frigideira antiaderente","Assadeira","Faca de chef","Tábua"],"care":"Receitas demonstrativas. Alergênicos: a panqueca leva ovo e aveia (pode conter glúten); o salmão é peixe; a omelete leva ovo e leite. Cuidado com facas e forno quente."}$c$::jsonb),
  ('marmitas-congelaveis', 'pt-BR', $c${"idea":"O congelador pode ser seu melhor aliado. Eu reúno receitas pensadas para congelar bem: você porciona, etiqueta e aquece sem perder sabor. Uma tarde de preparo resolve o almoço da semana inteira.","for_who":"Para quem não tem tempo de cozinhar durante a semana e quer almoço pronto e equilibrado no congelador.","not_for":"Não é para quem prefere comida feita na hora todos os dias.","outcomes":["Marmitas congeladas para os almoços da semana","Um método de porcionar, etiquetar e aquecer com segurança","Quatro preparos que congelam bem: carne com abóbora, sopa, omelete e arroz"],"method":[{"title":"Escolha o cardápio","text":"Combine a marmita de carne com abóbora, a sopa de grão-de-bico e a omelete de forno."},{"title":"Cozinhe as bases","text":"Prepare o arroz integral e os preparos principais na mesma tarde."},{"title":"Porcione e congele","text":"Resfrie, divida em potes, etiquete com a data e congele."},{"title":"Varie (opcional)","text":"Inclua o bowl grelhado e o molho de ervas para os dias frescos."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Uma tarde de preparo (cerca de 2 horas) por semana."},"needs":["Panela grande","Assadeira","Potes que vão ao freezer","Etiquetas ou fita"],"care":"Receitas demonstrativas. Alergênicos: a omelete leva ovo e leite. Resfrie antes de congelar, consuma em até 30 dias, descongele na geladeira e aqueça bem antes de comer."}$c$::jsonb),
  ('domingo-de-preparo', 'pt-BR', $c${"idea":"Uma tarde de domingo bem organizada vale por uma semana inteira. Eu te guio para fazer arroz, omelete de forno e sopa na mesma tarde, com mise en place para ganhar tempo — e você começa a segunda com a geladeira pronta.","for_who":"Para quem tem algumas horas livres no fim de semana e quer adiantar as refeições da semana de uma vez.","not_for":"Não é para quem não tem tempo nem espaço no congelador para preparos em quantidade.","outcomes":["Arroz, omelete de forno e sopa prontos na mesma tarde","Uma ordem de preparo que aproveita forno e fogão ao mesmo tempo","Porções guardadas para a semana"],"method":[{"title":"Organize antes","text":"Faça o mise en place: lave, corte e separe tudo antes de ligar o fogo."},{"title":"Forno e fogão juntos","text":"Coloque a omelete no forno enquanto o arroz integral e a sopa cozinham."},{"title":"Guarde","text":"Porcione, etiquete e separe o que vai para a geladeira e o que vai para o congelador."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Uma tarde de cerca de 2h30 por semana."},"needs":["Panela grande","Panela com tampa","Assadeira","Potes com tampa","Faca de chef e tábua"],"care":"Receitas demonstrativas. Alergênicos: a omelete leva ovo e leite. Resfrie antes de guardar, consuma o que fica na geladeira em poucos dias e aqueça bem antes de comer."}$c$::jsonb),
  ('noites-que-descansam', 'en', $c${"idea":"I won't give you rigid sleep rules. I suggest small tweaks — light, screens, breathing and a short bedtime ritual — for you to test one at a time and keep the ones that work. Sleeping better is a sum of details.","for_who":"For anyone who struggles to switch off at night, stays on screens until late or wakes up tired and wants to try simple changes.","not_for":"This is not a treatment for insomnia or other sleep disorders.","outcomes":["Eight sleep-hygiene tweaks tested in your own routine","A short stretching and breathing ritual before bed","A screens-off time you can actually keep"],"method":[{"title":"Adjust your space","text":"Start with the 8 sleep-hygiene tweaks: light, temperature, caffeine and screens."},{"title":"Build an evening routine","text":"Use the evening-routine guide to cut decisions at night and prepare the morning."},{"title":"Slow your body down","text":"Do the gentle 12-minute stretch and the 4-7-8 breathing before bed."},{"title":"Test and keep","text":"Try one tweak at a time, repeat what works and, if you like, run the 7-day screen experiment."}],"rhythm":{"sessions_per_week":7,"minutes_per_day":15,"note":"Every night for two weeks."},"needs":["A mat for stretching"],"care":"Educational content; not a substitute for professional advice. If trouble sleeping lasts for weeks or affects your day, see a health professional."}$c$::jsonb),
  ('autocuidado-em-pequenas-doses', 'en', $c${"idea":"Self-care doesn't have to be an impossible list. I fit into a few minutes: a light checklist, a morning ritual, a focus break and a stretch at the end of the day. Small doses, repeated, count more than one big day off.","for_who":"For anyone with busy days who always leaves self-care for later and wants short habits that fit the schedule.","not_for":"This is not emotional or psychological support.","outcomes":["A weekly checklist for sleep, movement, food and rest","A short morning ritual you repeat without effort","A way to make streaks work for you, without guilt"],"method":[{"title":"Look at your week","text":"Start with the weekly self-care checklist and pick one thing to look after."},{"title":"Start the day","text":"Add the 10-minute morning ritual on the mornings you can."},{"title":"Keep it guilt-free","text":"Learn when streaks help and organize your day around three priorities."},{"title":"Close the day (optional)","text":"Use the bedtime stretch and the 15-minute weekly review."}],"rhythm":{"sessions_per_week":5,"minutes_per_day":10,"note":"Two weeks; one short habit a day."},"needs":[],"care":"Educational content; not a substitute for professional advice. If you are going through a hard time, reach out to a mental health professional."}$c$::jsonb),
  ('semana-sob-controle', 'en', $c${"idea":"I am a simple planning system: a fifteen-minute review on Sunday, three priorities a day and breathing room in the calendar for the unexpected. The goal isn't to do more — it's to end the week knowing what mattered.","for_who":"For anyone who feels the week slipping away, is always putting out fires and wants a short planning ritual that works in real life.","not_for":"This is not project-management software or a corporate methodology.","outcomes":["A 15-minute weekly review that becomes a habit","Days organized in focus blocks with three priorities","Room in your calendar for yourself and for the unexpected"],"method":[{"title":"Review","text":"Do the weekly review: look back, choose what to keep and plan with slack."},{"title":"Prioritize the day","text":"Organize each day in focus blocks with no more than three priorities."},{"title":"Sustain it","text":"Use streaks as support, not pressure, and the checklist so you don't forget yourself."},{"title":"Adjust (optional)","text":"Try fewer screens at night and a morning ritual to start the day calmly."}],"rhythm":{"sessions_per_week":5,"minutes_per_day":10,"note":"The review takes 15 minutes once a week."},"needs":["A planner or calendar","Pen and paper or a notes app"],"care":"Educational content; not a substitute for professional advice."}$c$::jsonb),
  ('foco-sem-telas', 'en', $c${"idea":"Attention can be trained. I propose a guided experiment: fewer screens at night, breathing between tasks and focus blocks during the day. No extremes and no guilt — you test, notice and keep what works.","for_who":"For anyone who picks up the phone without noticing, struggles to concentrate and stays on screens until bedtime.","not_for":"This is not a treatment for digital dependence or diagnosed attention difficulties.","outcomes":["A screens-off time at night you can keep","Focus blocks with three priorities during the day","A short breathing technique to refocus between tasks"],"method":[{"title":"Run the experiment","text":"Follow the guided 7-day experiment to cut screens at night."},{"title":"Breathe between tasks","text":"Use 4-7-8 breathing when switching activities and before bed."},{"title":"Protect your focus","text":"Organize the day in blocks with three priorities and adjust your sleep hygiene."},{"title":"Go further (optional)","text":"Build an evening routine and do the weekly review to see what changed."}],"rhythm":{"sessions_per_week":7,"minutes_per_day":10,"note":"Two weeks; the screen experiment lasts 7 days."},"needs":[],"care":"Educational content; not a substitute for professional advice."}$c$::jsonb),
  ('forca-em-casa-com-elastico', 'en', $c${"idea":"You can get stronger without a gym. With me the order is clear: technique first, bodyweight next and only then the resistance band. Four weeks to progress safely at home.","for_who":"For anyone who trains at home, knows the basics or is just starting, and wants to build strength with little equipment.","not_for":"This is not for heavy-load training or competition prep.","outcomes":["A squat with corrected technique","Command of a full-body bodyweight workout","Band progressions to keep improving at home"],"method":[{"title":"Fix your technique","text":"Correct the 5 common squat mistakes before adding any load."},{"title":"Bodyweight","text":"Do the full-body functional workout until it feels comfortable."},{"title":"Add the band","text":"Follow the band strength workout and include the 12-minute core block."},{"title":"Go further (optional)","text":"Practice the three basic patterns and hip mobility on light days."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":30,"note":"Four weeks, with a rest day between workouts."},"needs":["Resistance band","Exercise mat","Some clear floor space"],"care":"Educational content; not a substitute for professional advice. Stop if you feel pain and see a qualified professional; if you have a health condition, talk to your doctor before you start. Check the band before use and discard it if it is cracked or dried out."}$c$::jsonb),
  ('core-e-postura-em-3-semanas', 'en', $c${"idea":"Posture isn't about being stiff: it's having the stability and mobility to move well. I combine short core blocks, hip mobility and technique to support your body in training and everyday life — in sessions that fit any break.","for_who":"For anyone who sits a lot, feels stiff and wants a stable base to train and live better.","not_for":"This is not a treatment for back pain or injury rehabilitation.","outcomes":["A 12-minute core block you can do anywhere","More hip mobility for long days of sitting","Technique to hold good posture in strength moves"],"method":[{"title":"Stability","text":"Start with the 12-minute core block, prioritizing control of the movement."},{"title":"Technique","text":"Fix your squat with the 5 common mistakes video."},{"title":"Mobility","text":"Add the 8-minute hip mobility on non-training days."},{"title":"Bring it together","text":"Use the full-body functional workout and, if you like, move on to basic strength or bands."}],"rhythm":{"sessions_per_week":4,"minutes_per_day":15,"note":"Three weeks of short sessions."},"needs":["Exercise mat"],"care":"Educational content; not a substitute for professional advice. Stop if you feel pain and see a qualified professional; if you have a health condition, talk to your doctor before you start."}$c$::jsonb),
  ('mobilidade-para-correr-melhor', 'en', $c${"idea":"Running well starts before the run. I help you prepare your body — warm-up, loose hips, core and the right shoes — so you run without stiffness and come back wanting to go again.","for_who":"For anyone who already walks or runs and feels stiff in the hips, ankles or body before or after running.","not_for":"This is not an injury treatment or a running training plan.","outcomes":["A 5-minute warm-up before every run","A hip mobility routine for days spent sitting","A more stable core to run with more control"],"method":[{"title":"Warm up","text":"Do the 5-minute warm-up for ankles, hips and breathing before heading out."},{"title":"Free your hips","text":"Use the 8-minute hip mobility after running or at the end of the day."},{"title":"Build the base","text":"Fix your squat technique and add the 12-minute core block twice a week."},{"title":"Choose well (optional)","text":"Review your shoes with the guide and go back to walk-run if you are restarting."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":15,"note":"Two weeks, alongside your runs."},"needs":["Running shoes","Exercise mat"],"care":"Educational content; not a substitute for professional advice. Stop if you feel pain and see a qualified professional; if you have a health condition, talk to your doctor before you start."}$c$::jsonb),
  ('primeiro-intervalado', 'en', $c${"idea":"Intervals don't have to hurt. I am the bridge between walk-run and your first short repeats: a proper warm-up, a solid base and generous recovery between efforts. You finish wanting more, not exhausted.","for_who":"For anyone who already walk-runs comfortably and wants to carefully try their first interval sessions.","not_for":"Not for complete beginners (start with a walk-run program) or anyone looking for high-intensity training.","outcomes":["A solid walk-run base","Your first light interval sessions, with generous recovery","A warm-up and mobility routine before and after"],"method":[{"title":"Always warm up","text":"Do the 5-minute warm-up before every run."},{"title":"Build the base","text":"Repeat the walk-run until it feels comfortable."},{"title":"First repeats","text":"Follow the light interval session: short efforts and generous recovery, once a week."},{"title":"Recover","text":"Loosen your hips after running and, if you like, add core and functional training."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":25,"note":"Four weeks; at most one interval session a week."},"needs":["Running shoes","A watch or phone stopwatch","Water"],"care":"Educational content; not a substitute for professional advice. Stop if you feel pain and see a qualified professional; if you have a health condition, talk to your doctor before you start. If you feel unusual shortness of breath, dizziness or chest pain, stop immediately."}$c$::jsonb),
  ('supermercado-sem-misterio', 'en', $c${"idea":"Better choices start before the plate: on the list and in the cart. I help you build a list that avoids waste, read labels for what matters and turn your groceries into balanced plates — without demonizing any food.","for_who":"For anyone who gets lost at the supermarket, buys on impulse or doesn't know where to start with a label.","not_for":"Not for anyone who needs an individual diet or guidance for allergies and medical conditions.","outcomes":["A smart shopping list based on your week","Reading labels starting with serving size and ingredients","Balanced plates built from what you bought"],"method":[{"title":"Plan the list","text":"Build the list from the week's meals and what you already have at home."},{"title":"Read the label","text":"See the 5 things to check first and what to ignore on the package."},{"title":"Cart to plate","text":"Use the hand method and add simple sources of fiber."},{"title":"Go further (optional)","text":"Plan meals in 30 minutes and keep practical snacks on hand."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"About 30 minutes a week, alongside your grocery trips."},"needs":["Paper or a notes app for the list"],"care":"Educational content; not a substitute for advice from a dietitian or doctor. No individual calorie or weight targets. If you have a food allergy or intolerance, always check the ingredient list."}$c$::jsonb),
  ('lanches-e-proteina-no-dia-a-dia', 'en', $c${"idea":"Afternoon hunger isn't a lack of willpower: often it's a lack of planning. I bring together snack ideas, quick breakfasts and general concepts on spreading protein through the day — with no individual targets and no fuss.","for_who":"For anyone who arrives starving in the late afternoon, grabs whatever is around and wants practical combos to eat better between meals.","not_for":"Not for anyone who needs individual protein targets or a meal plan.","outcomes":["Practical snack combos for the afternoon","Three 5-minute breakfasts","A general understanding of why to spread protein across meals"],"method":[{"title":"Snacks","text":"Pick two or three snack combos and keep the ingredients on hand."},{"title":"Protein through the day","text":"Learn the general concepts of spreading protein across meals."},{"title":"Build the plate","text":"Use the hand method and a quick breakfast to start well."},{"title":"Go further (optional)","text":"See the basics of pre- and post-workout eating, fiber and hydration."}],"rhythm":{"sessions_per_week":null,"minutes_per_day":10,"note":"Two weeks; one tweak at a time."},"needs":[],"care":"Educational content; not a substitute for advice from a dietitian or doctor. No individual calorie or weight targets. If you have a food allergy or intolerance, adapt the combos."}$c$::jsonb),
  ('planejamento-de-refeicoes-em-4-semanas', 'en', $c${"idea":"Thirty minutes a week to decide, shop and prep. I am a planning method that fits your routine: a simple menu, a shopping list, breakfast sorted, water nearby and balanced plates without a scale. In four weeks, it becomes a habit.","for_who":"For anyone who decides what to eat at the last minute, wastes food and wants a planning routine that lasts.","not_for":"Not for anyone who needs a prescribed menu or a diet for a health condition.","outcomes":["A 30-minute weekly ritual to plan your meals","A shopping list that matches the menu, with less waste","Breakfast and hydration sorted in your routine"],"method":[{"title":"Decide","text":"Use the 30-minute method to choose the week's meals."},{"title":"Shop","text":"Turn the menu into a smart shopping list."},{"title":"Sort the basics","text":"Pick 5-minute breakfasts and adjust hydration to your body's signals."},{"title":"Repeat and refine","text":"Repeat the cycle for four weeks; if you like, use the hand method and label reading."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"About 30 minutes of planning a week."},"needs":["Paper or a notes app","Containers for prepped food"],"care":"Educational content; not a substitute for advice from a dietitian or doctor. No individual calorie or weight targets."}$c$::jsonb),
  ('energia-para-treinar', 'en', $c${"idea":"Training well also depends on what happens outside the workout. I bring together general principles for energy: drinking water according to your body, eating well before and after and spreading protein through the day — educational and without excess.","for_who":"For anyone who has started training and wants to understand the basics of hydration and eating around workouts.","not_for":"Not for athletes who need an individual nutrition strategy or supplementation.","outcomes":["General hydration principles for daily life and training","Practical ideas for eating before and after workouts","A general understanding of spreading protein through the day"],"method":[{"title":"Hydrate","text":"Read about hydration and notice your body's signals on training days."},{"title":"Before and after","text":"See the basics of pre- and post-workout eating, without excess."},{"title":"Breakfast","text":"Pick one of the 5-minute ideas for early training days."},{"title":"Protein through the day","text":"Learn why to spread protein and, if you like, explore snacks and fiber."}],"rhythm":{"sessions_per_week":null,"minutes_per_day":10,"note":"Two weeks, alongside your training days."},"needs":[],"care":"Educational content; not a substitute for advice from a dietitian or doctor. No individual calorie or weight targets. This is not a supplement recommendation."}$c$::jsonb),
  ('tecnicas-de-faca-e-mise-en-place', 'en', $c${"idea":"Every fast kitchen has the same foundation: sharp knives and an organized counter before the heat goes on. I teach you these two habits and apply them to an all-purpose sauce and a complete bowl, so you feel the difference at your first dinner.","for_who":"For anyone who is slow in the kitchen, gets lost halfway through a recipe or is wary of using a knife.","not_for":"This is not a professional cooking course.","outcomes":["Sharp, well-kept and safer knives","The habit of mise en place before cooking","An herb sauce and a complete bowl in your repertoire"],"method":[{"title":"Care for the knife","text":"Learn to sharpen and maintain your knives — a sharp knife is safer."},{"title":"Organize the counter","text":"Practice mise en place: everything cut and set out before the heat."},{"title":"Apply it","text":"Make the herb sauce and build the chicken bowl with roasted vegetables."},{"title":"Go further (optional)","text":"Use the same techniques for oven-baked salmon and brown rice."}],"rhythm":{"sessions_per_week":2,"minutes_per_day":30,"note":"Two weeks; cook once or twice a week."},"needs":["Chef's knife","Cutting board","Whetstone or honing steel","Small bowls"],"care":"Demo recipes; check the allergens (salmon is fish). Always cut with your fingertips tucked in and keep knives away from the edge of the counter."}$c$::jsonb),
  ('cozinha-rapida-do-dia-a-dia', 'en', $c${"idea":"Good everyday food doesn't need many steps. I bring together practical recipes from breakfast to oven dinners — a three-ingredient pancake, herb sauce, a grilled bowl and salmon — so you get flavor without spending the evening in the kitchen.","for_who":"For anyone who gets home tired and wants quick, tasty recipes to vary the week.","not_for":"Not for anyone looking for special-occasion recipes or advanced techniques.","outcomes":["A three-ingredient breakfast in a few minutes","An all-purpose sauce that lifts any dish","Two complete dinners: a grilled bowl and oven-baked salmon"],"method":[{"title":"Breakfast","text":"Start with the oat and banana pancake."},{"title":"The all-rounder","text":"Make the herb sauce; it keeps for days in the fridge."},{"title":"Dinners","text":"Cook the grilled chicken bowl and the oven-baked salmon with sweet potato."},{"title":"Speed up","text":"Keep your knives sharp and, if you like, get ahead with the oven omelet and mise en place."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":30,"note":"Two weeks; pick the days you want to cook."},"needs":["Non-stick frying pan","Baking tray","Chef's knife","Cutting board"],"care":"Demo recipes. Allergens: the pancake contains egg and oats (may contain gluten); salmon is fish; the omelet contains egg and milk. Take care with knives and a hot oven."}$c$::jsonb),
  ('marmitas-congelaveis', 'en', $c${"idea":"Your freezer can be your best ally. I bring together recipes designed to freeze well: you portion, label and reheat without losing flavor. One afternoon of prep covers lunch for the whole week.","for_who":"For anyone without time to cook during the week who wants ready, balanced lunches in the freezer.","not_for":"Not for anyone who prefers freshly cooked food every day.","outcomes":["Frozen meals for the week's lunches","A method to portion, label and reheat safely","Four recipes that freeze well: beef with squash, soup, omelet and rice"],"method":[{"title":"Choose the menu","text":"Combine the beef and squash meal, the chickpea soup and the oven omelet."},{"title":"Cook the bases","text":"Make the brown rice and the main dishes in the same afternoon."},{"title":"Portion and freeze","text":"Cool, divide into containers, label with the date and freeze."},{"title":"Vary (optional)","text":"Add the grilled bowl and herb sauce for fresh days."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"One prep afternoon (about 2 hours) a week."},"needs":["Large pot","Baking tray","Freezer-safe containers","Labels or tape"],"care":"Demo recipes. Allergens: the omelet contains egg and milk. Cool before freezing, eat within 30 days, thaw in the fridge and reheat thoroughly before eating."}$c$::jsonb),
  ('domingo-de-preparo', 'en', $c${"idea":"One well-organized Sunday afternoon is worth a whole week. I guide you through rice, oven omelet and soup in the same afternoon, with mise en place to save time — and you start Monday with the fridge ready.","for_who":"For anyone with a few free hours at the weekend who wants to get the week's meals done in one go.","not_for":"Not for anyone without the time or freezer space for batch cooking.","outcomes":["Rice, oven omelet and soup ready in the same afternoon","A cooking order that uses oven and stovetop at the same time","Portions stored for the week"],"method":[{"title":"Organize first","text":"Do the mise en place: wash, cut and set out everything before the heat goes on."},{"title":"Oven and stove together","text":"Put the omelet in the oven while the brown rice and soup cook."},{"title":"Store","text":"Portion, label and separate what goes in the fridge and what goes in the freezer."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"One afternoon of about 2.5 hours a week."},"needs":["Large pot","Pot with lid","Baking tray","Containers with lids","Chef's knife and cutting board"],"care":"Demo recipes. Allergens: the omelet contains egg and milk. Cool before storing, eat refrigerated food within a few days and reheat thoroughly before eating."}$c$::jsonb),
  ('noites-que-descansam', 'es', $c${"idea":"No te voy a dar reglas rígidas de sueño. Te propongo ajustes pequeños — luz, pantallas, respiración y un ritual corto antes de acostarte — para que los pruebes uno a la vez y te quedes con los que funcionen. Dormir mejor es una suma de detalles.","for_who":"Para quien tarda en desconectarse por la noche, se queda en las pantallas hasta tarde o se despierta cansado y quiere probar cambios sencillos.","not_for":"No es un tratamiento para el insomnio ni para otros trastornos del sueño.","outcomes":["Ocho ajustes de higiene del sueño probados en tu rutina","Un ritual corto de estiramiento y respiración antes de acostarte","Una hora para apagar las pantallas que puedas mantener"],"method":[{"title":"Ajusta el ambiente","text":"Empieza por los 8 ajustes de higiene del sueño: luz, temperatura, cafeína y pantallas."},{"title":"Arma la rutina nocturna","text":"Usa la guía de rutina nocturna para reducir decisiones y preparar la mañana."},{"title":"Calma el cuerpo","text":"Haz el estiramiento suave de 12 minutos y la respiración 4-7-8 antes de acostarte."},{"title":"Prueba y mantén","text":"Prueba un ajuste a la vez, repite los que funcionen y, si quieres, haz el experimento de 7 días sin pantallas."}],"rhythm":{"sessions_per_week":7,"minutes_per_day":15,"note":"Todas las noches, durante dos semanas."},"needs":["Una esterilla para estirar"],"care":"Contenido educativo; no sustituye la orientación profesional. Si la dificultad para dormir dura semanas o afecta tu día, busca a un profesional de la salud."}$c$::jsonb),
  ('autocuidado-em-pequenas-doses', 'es', $c${"idea":"El autocuidado no tiene que ser una lista imposible. Quepo en pocos minutos: un checklist ligero, un ritual matutino, una pausa de enfoque y un estiramiento al final del día. Pequeñas dosis, repetidas, cuentan más que un gran día libre.","for_who":"Para quien vive días ajetreados, siempre deja su propio cuidado para después y quiere gestos cortos que quepan en la agenda.","not_for":"No es acompañamiento emocional ni psicológico.","outcomes":["Un checklist semanal de sueño, movimiento, comida y descanso","Un ritual matutino corto que repites sin esfuerzo","Una forma de usar las rachas a tu favor, sin culpa"],"method":[{"title":"Mira tu semana","text":"Empieza por el checklist semanal de autocuidado y elige un punto para cuidar."},{"title":"Empieza el día","text":"Incluye el ritual matutino de 10 minutos las mañanas que puedas."},{"title":"Mantén sin presión","text":"Entiende cuándo la racha ayuda y organiza el día en tres prioridades."},{"title":"Cierra el día (opcional)","text":"Usa el estiramiento antes de dormir y la revisión semanal de 15 minutos."}],"rhythm":{"sessions_per_week":5,"minutes_per_day":10,"note":"Dos semanas; un gesto corto por día."},"needs":[],"care":"Contenido educativo; no sustituye la orientación profesional. Si estás pasando por un momento difícil, busca apoyo de un profesional de salud mental."}$c$::jsonb),
  ('semana-sob-controle', 'es', $c${"idea":"Soy un sistema sencillo de planificación: quince minutos de revisión el domingo, tres prioridades por día y margen en el calendario para lo imprevisto. El objetivo no es hacer más — es terminar la semana sabiendo qué importó.","for_who":"Para quien siente que la semana se le escapa, vive apagando incendios y quiere un ritual corto de planificación que funcione en la vida real.","not_for":"No es un software de gestión de proyectos ni una metodología corporativa.","outcomes":["Una revisión semanal de 15 minutos que se vuelve hábito","Días organizados en bloques de enfoque con tres prioridades","Espacio en el calendario para ti y para lo imprevisto"],"method":[{"title":"Revisa","text":"Haz la revisión semanal: mira atrás, elige qué mantener y planifica con margen."},{"title":"Prioriza el día","text":"Organiza cada día en bloques de enfoque con un máximo de tres prioridades."},{"title":"Sostén","text":"Usa las rachas como apoyo, no como presión, y el checklist para no olvidarte de ti."},{"title":"Ajusta (opcional)","text":"Prueba menos pantallas por la noche y un ritual matutino para empezar el día con calma."}],"rhythm":{"sessions_per_week":5,"minutes_per_day":10,"note":"La revisión dura 15 minutos una vez por semana."},"needs":["Agenda o calendario","Papel y lápiz o una app de notas"],"care":"Contenido educativo; no sustituye la orientación profesional."}$c$::jsonb),
  ('foco-sem-telas', 'es', $c${"idea":"La atención se entrena. Te propongo un experimento guiado: menos pantallas por la noche, respiración en las transiciones y bloques de enfoque durante el día. Sin radicalismos y sin culpa — pruebas, observas y te quedas con lo que funcione.","for_who":"Para quien toma el celular sin darse cuenta, tiene dificultad para concentrarse y se queda en las pantallas hasta la hora de dormir.","not_for":"No es un tratamiento para la dependencia digital ni para dificultades de atención diagnosticadas.","outcomes":["Una hora por la noche para apagar las pantallas que puedas mantener","Bloques de enfoque con tres prioridades durante el día","Una respiración corta para volver al foco en las transiciones"],"method":[{"title":"Haz el experimento","text":"Sigue el experimento guiado de 7 días para reducir pantallas por la noche."},{"title":"Respira entre tareas","text":"Usa la respiración 4-7-8 al cambiar de actividad y antes de dormir."},{"title":"Protege el enfoque","text":"Organiza el día en bloques con tres prioridades y ajusta la higiene del sueño."},{"title":"Ve más allá (opcional)","text":"Arma la rutina nocturna y haz la revisión semanal para ver qué cambió."}],"rhythm":{"sessions_per_week":7,"minutes_per_day":10,"note":"Dos semanas; el experimento de pantallas dura 7 días."},"needs":[],"care":"Contenido educativo; no sustituye la orientación profesional."}$c$::jsonb),
  ('forca-em-casa-com-elastico', 'es', $c${"idea":"Se puede ganar fuerza sin gimnasio. Conmigo el orden es claro: primero la técnica, después el propio peso y solo entonces la banda de resistencia. Cuatro semanas para progresar en casa con seguridad.","for_who":"Para quien entrena en casa, ya conoce lo básico o está empezando, y quiere ganar fuerza con poco equipo.","not_for":"No es para entrenar con cargas altas ni para preparar competencias.","outcomes":["Una sentadilla con la técnica ajustada","Dominio de un entrenamiento de cuerpo entero con tu propio peso","Progresiones con banda para seguir avanzando en casa"],"method":[{"title":"Ajusta la técnica","text":"Corrige los 5 errores comunes de la sentadilla antes de añadir carga."},{"title":"Propio peso","text":"Haz el entrenamiento funcional de cuerpo entero hasta que te resulte cómodo."},{"title":"Añade la banda","text":"Sigue el entrenamiento de fuerza con banda e incluye el core de 12 minutos."},{"title":"Ve más allá (opcional)","text":"Practica los tres patrones básicos y la movilidad de cadera en los días suaves."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":30,"note":"Cuatro semanas, con un día de descanso entre entrenamientos."},"needs":["Banda de resistencia","Esterilla","Un espacio libre en el suelo"],"care":"Contenido educativo; no sustituye la orientación profesional. Detente si sientes dolor y busca a un profesional habilitado; si tienes alguna condición de salud, consulta a tu médico antes de empezar. Revisa la banda antes de usarla y descártala si está agrietada o reseca."}$c$::jsonb),
  ('core-e-postura-em-3-semanas', 'es', $c${"idea":"La postura no es quedarse rígido: es tener estabilidad y movilidad para moverse bien. Junto bloques cortos de core, movilidad de cadera y técnica para sostener el cuerpo en el entrenamiento y en el día a día — en sesiones que caben en cualquier pausa.","for_who":"Para quien pasa mucho tiempo sentado, siente el cuerpo rígido y quiere una base de estabilidad para entrenar y vivir mejor.","not_for":"No es un tratamiento para el dolor de espalda ni rehabilitación de lesiones.","outcomes":["Un bloque de core de 12 minutos que puedes hacer en cualquier lugar","Más movilidad de cadera para quien pasa el día sentado","Técnica para mantener la postura en los movimientos de fuerza"],"method":[{"title":"Estabilidad","text":"Empieza por el core de 12 minutos, priorizando el control del movimiento."},{"title":"Técnica","text":"Ajusta la sentadilla con el video de los 5 errores comunes."},{"title":"Movilidad","text":"Incluye la movilidad de cadera de 8 minutos en los días sin entrenamiento."},{"title":"Integra","text":"Usa el entrenamiento funcional de cuerpo entero y, si quieres, avanza a fuerza básica o banda."}],"rhythm":{"sessions_per_week":4,"minutes_per_day":15,"note":"Tres semanas de sesiones cortas."},"needs":["Esterilla"],"care":"Contenido educativo; no sustituye la orientación profesional. Detente si sientes dolor y busca a un profesional habilitado; si tienes alguna condición de salud, consulta a tu médico antes de empezar."}$c$::jsonb),
  ('mobilidade-para-correr-melhor', 'es', $c${"idea":"Correr bien empieza antes de correr. Te ayudo a preparar el cuerpo — calentamiento, cadera suelta, core y unas buenas zapatillas — para que corras sin rigidez y vuelvas con ganas de repetir.","for_who":"Para quien ya camina o corre y siente la cadera, los tobillos o el cuerpo rígidos antes o después de correr.","not_for":"No es un tratamiento para lesiones ni un plan de entrenamiento de carrera.","outcomes":["Un calentamiento de 5 minutos antes de cada carrera","Una secuencia de movilidad de cadera para los días sentado","Un core más estable para correr con más control"],"method":[{"title":"Calienta","text":"Haz el calentamiento de 5 minutos para tobillos, cadera y respiración antes de salir."},{"title":"Suelta la cadera","text":"Usa la movilidad de cadera de 8 minutos después de correr o al final del día."},{"title":"Fortalece la base","text":"Ajusta la técnica de la sentadilla e incluye el core de 12 minutos dos veces por semana."},{"title":"Elige bien (opcional)","text":"Revisa tus zapatillas con la guía y vuelve a caminar y trotar si estás retomando."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":15,"note":"Dos semanas, junto con tus carreras."},"needs":["Zapatillas de correr","Esterilla"],"care":"Contenido educativo; no sustituye la orientación profesional. Detente si sientes dolor y busca a un profesional habilitado; si tienes alguna condición de salud, consulta a tu médico antes de empezar."}$c$::jsonb),
  ('primeiro-intervalado', 'es', $c${"idea":"El interválico no tiene que ser sufrimiento. Soy el puente entre caminar y trotar y tus primeras series cortas: buen calentamiento, base consolidada y recuperación generosa entre esfuerzos. Terminas con ganas de más, no agotado.","for_who":"Para quien ya alterna caminar y trotar con comodidad y quiere probar, con cuidado, sus primeros entrenamientos interválicos.","not_for":"No es para quien empieza desde cero (empieza por un programa de caminar y trotar) ni para quien busca entrenamiento de alta intensidad.","outcomes":["Una base de caminar y trotar consolidada","Tus primeros interválicos suaves, con recuperación generosa","Una rutina de calentamiento y movilidad antes y después"],"method":[{"title":"Calienta siempre","text":"Haz el calentamiento de 5 minutos antes de cada salida."},{"title":"Consolida la base","text":"Repite el caminar y trotar hasta que te resulte cómodo."},{"title":"Primeras series","text":"Sigue el interválico suave: esfuerzos cortos y recuperación generosa, una vez por semana."},{"title":"Recupera","text":"Suelta la cadera después de correr y, si quieres, complementa con core y entrenamiento funcional."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":25,"note":"Cuatro semanas; como máximo un interválico por semana."},"needs":["Zapatillas de correr","Reloj o cronómetro en el celular","Agua"],"care":"Contenido educativo; no sustituye la orientación profesional. Detente si sientes dolor y busca a un profesional habilitado; si tienes alguna condición de salud, consulta a tu médico antes de empezar. Si sientes falta de aire fuera de lo normal, mareo o dolor en el pecho, detente de inmediato."}$c$::jsonb),
  ('supermercado-sem-misterio', 'es', $c${"idea":"Las mejores elecciones empiezan antes del plato: en la lista y en el carrito. Te ayudo a armar una lista que evita el desperdicio, leer la etiqueta por lo que importa y convertir la compra en platos equilibrados — sin demonizar ningún alimento.","for_who":"Para quien se pierde en el supermercado, compra por impulso o no sabe por dónde empezar a leer una etiqueta.","not_for":"No es para quien necesita una dieta individual u orientación para alergias y enfermedades.","outcomes":["Una lista de compras inteligente basada en tu semana","Lectura de etiquetas empezando por la porción y los ingredientes","Platos equilibrados armados con lo que compraste"],"method":[{"title":"Planifica la lista","text":"Arma la lista a partir de las comidas de la semana y de lo que ya tienes en casa."},{"title":"Lee la etiqueta","text":"Mira las 5 cosas que conviene revisar primero y lo que puedes ignorar del envase."},{"title":"Del carrito al plato","text":"Usa el método de la mano e incluye fuentes sencillas de fibra."},{"title":"Ve más allá (opcional)","text":"Planifica comidas en 30 minutos y ten meriendas prácticas a mano."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Unos 30 minutos por semana, acompañando tus idas al supermercado."},"needs":["Papel o app de notas para la lista"],"care":"Contenido educativo; no sustituye la orientación de un nutricionista ni de un médico. No incluye metas individuales de calorías ni de peso. Si tienes alergia o intolerancia alimentaria, revisa siempre la lista de ingredientes."}$c$::jsonb),
  ('lanches-e-proteina-no-dia-a-dia', 'es', $c${"idea":"El hambre de la tarde no es falta de voluntad: muchas veces es falta de plan. Reúno ideas de meriendas, desayunos rápidos y conceptos generales sobre repartir la proteína a lo largo del día — sin metas individuales y sin complicaciones.","for_who":"Para quien llega con mucha hambre al final de la tarde, pica lo que encuentra y quiere combinaciones prácticas para comer mejor entre comidas.","not_for":"No es para quien necesita metas individuales de proteína o un plan alimentario.","outcomes":["Combinaciones de merienda prácticas para la tarde","Tres desayunos de 5 minutos","Una idea general de por qué repartir la proteína en las comidas"],"method":[{"title":"Meriendas","text":"Elige dos o tres combinaciones de merienda y ten los ingredientes a mano."},{"title":"Proteína en el día","text":"Entiende los conceptos generales de repartir la proteína entre las comidas."},{"title":"Arma el plato","text":"Usa el método de la mano y un desayuno rápido para empezar bien."},{"title":"Ve más allá (opcional)","text":"Mira lo básico del antes y después del entrenamiento, fibras e hidratación."}],"rhythm":{"sessions_per_week":null,"minutes_per_day":10,"note":"Dos semanas; un ajuste a la vez."},"needs":[],"care":"Contenido educativo; no sustituye la orientación de un nutricionista ni de un médico. No incluye metas individuales de calorías ni de peso. Si tienes alergia o intolerancia alimentaria, adapta las combinaciones."}$c$::jsonb),
  ('planejamento-de-refeicoes-em-4-semanas', 'es', $c${"idea":"Treinta minutos por semana para decidir, comprar y preparar. Soy un método de planificación que cabe en tu rutina: menú sencillo, lista de compras, desayuno resuelto, agua cerca y platos equilibrados sin báscula. En cuatro semanas, se vuelve hábito.","for_who":"Para quien decide qué comer a último momento, desperdicia comida y quiere una rutina de planificación que dure.","not_for":"No es para quien necesita un menú prescrito o una dieta por una condición de salud.","outcomes":["Un ritual semanal de 30 minutos para planificar las comidas","Una lista de compras alineada con el menú, con menos desperdicio","Desayuno e hidratación resueltos en la rutina"],"method":[{"title":"Decide","text":"Usa el método de 30 minutos para elegir las comidas de la semana."},{"title":"Compra","text":"Convierte el menú en una lista de compras inteligente."},{"title":"Resuelve lo básico","text":"Elige desayunos de 5 minutos y ajusta la hidratación a las señales del cuerpo."},{"title":"Repite y afina","text":"Repite el ciclo durante cuatro semanas; si quieres, usa el método de la mano y la lectura de etiquetas."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Unos 30 minutos de planificación por semana."},"needs":["Papel o app de notas","Recipientes para guardar preparaciones"],"care":"Contenido educativo; no sustituye la orientación de un nutricionista ni de un médico. No incluye metas individuales de calorías ni de peso."}$c$::jsonb),
  ('energia-para-treinar', 'es', $c${"idea":"Entrenar bien también depende de lo que pasa fuera del entrenamiento. Reúno principios generales para tener energía: beber agua según tu cuerpo, comer bien antes y después y repartir la proteína en el día — de forma educativa, sin exageraciones.","for_who":"Para quien empezó a entrenar y quiere entender lo básico de hidratación y alimentación alrededor del entrenamiento.","not_for":"No es para atletas que necesitan una estrategia nutricional individual o suplementación.","outcomes":["Principios generales de hidratación en el día a día y en el entrenamiento","Ideas prácticas para comer antes y después de entrenar","Una idea general de cómo repartir la proteína en el día"],"method":[{"title":"Hidrátate","text":"Lee sobre hidratación y observa las señales del cuerpo en los días de entrenamiento."},{"title":"Antes y después","text":"Mira lo básico del antes y después del entrenamiento, sin exageraciones."},{"title":"Desayuno","text":"Elige una de las ideas de 5 minutos para los días en que entrenas temprano."},{"title":"Proteína en el día","text":"Entiende por qué repartir la proteína y, si quieres, explora meriendas y fibras."}],"rhythm":{"sessions_per_week":null,"minutes_per_day":10,"note":"Dos semanas, acompañando tus días de entrenamiento."},"needs":[],"care":"Contenido educativo; no sustituye la orientación de un nutricionista ni de un médico. No incluye metas individuales de calorías ni de peso. No es una recomendación de suplementos."}$c$::jsonb),
  ('tecnicas-de-faca-e-mise-en-place', 'es', $c${"idea":"Toda cocina rápida tiene la misma base: cuchillos afilados y mesada ordenada antes de encender el fuego. Te enseño esos dos hábitos y los aplico en una salsa comodín y en un bowl completo, para que notes la diferencia en la primera cena.","for_who":"Para quien tarda en la cocina, se enreda a mitad de la receta o tiene miedo de usar el cuchillo.","not_for":"No es un curso profesional de cocina.","outcomes":["Cuchillos afilados, bien cuidados y más seguros","El hábito del mise en place antes de cocinar","Una salsa de hierbas y un bowl completo en tu repertorio"],"method":[{"title":"Cuida el cuchillo","text":"Aprende a afilar y mantener los cuchillos — un cuchillo afilado es más seguro."},{"title":"Ordena la mesada","text":"Practica el mise en place: todo cortado y separado antes del fuego."},{"title":"Aplícalo","text":"Haz la salsa de hierbas y arma el bowl de pollo con verduras asadas."},{"title":"Ve más allá (opcional)","text":"Usa las mismas técnicas en el salmón al horno y el arroz integral."}],"rhythm":{"sessions_per_week":2,"minutes_per_day":30,"note":"Dos semanas; cocina una o dos veces por semana."},"needs":["Cuchillo de chef","Tabla","Piedra o chaira para afilar","Bowls pequeños"],"care":"Recetas demostrativas; revisa los alérgenos (el salmón es pescado). Corta siempre con las puntas de los dedos recogidas y mantén los cuchillos lejos del borde de la mesada."}$c$::jsonb),
  ('cozinha-rapida-do-dia-a-dia', 'es', $c${"idea":"La buena comida del día a día no necesita muchos pasos. Reúno preparaciones prácticas del desayuno a la cena al horno — panqueque de tres ingredientes, salsa de hierbas, bowl a la plancha y salmón — para que tengas sabor sin pasar la noche en la cocina.","for_who":"Para quien llega cansado a casa y quiere recetas rápidas y sabrosas para variar la semana.","not_for":"No es para quien busca recetas para ocasiones especiales o técnicas avanzadas.","outcomes":["Un desayuno de tres ingredientes en pocos minutos","Una salsa comodín que cambia cualquier plato","Dos cenas completas: bowl a la plancha y salmón al horno"],"method":[{"title":"Desayuno","text":"Empieza por el panqueque de avena y banana."},{"title":"El comodín","text":"Prepara la salsa de hierbas; dura días en la heladera."},{"title":"Cenas","text":"Haz el bowl de pollo a la plancha y el salmón al horno con batata."},{"title":"Agiliza","text":"Mantén los cuchillos afilados y, si quieres, adelanta la semana con el omelet al horno y el mise en place."}],"rhythm":{"sessions_per_week":3,"minutes_per_day":30,"note":"Dos semanas; elige los días en que quieras cocinar."},"needs":["Sartén antiadherente","Fuente para horno","Cuchillo de chef","Tabla"],"care":"Recetas demostrativas. Alérgenos: el panqueque lleva huevo y avena (puede contener gluten); el salmón es pescado; el omelet lleva huevo y leche. Cuidado con los cuchillos y el horno caliente."}$c$::jsonb),
  ('marmitas-congelaveis', 'es', $c${"idea":"El congelador puede ser tu mejor aliado. Reúno recetas pensadas para congelarse bien: porcionas, etiquetas y recalientas sin perder sabor. Una tarde de preparación resuelve el almuerzo de toda la semana.","for_who":"Para quien no tiene tiempo de cocinar durante la semana y quiere almuerzos listos y equilibrados en el congelador.","not_for":"No es para quien prefiere comida recién hecha todos los días.","outcomes":["Viandas congeladas para los almuerzos de la semana","Un método para porcionar, etiquetar y recalentar con seguridad","Cuatro preparaciones que se congelan bien: carne con calabaza, sopa, omelet y arroz"],"method":[{"title":"Elige el menú","text":"Combina la vianda de carne con calabaza, la sopa de garbanzos y el omelet al horno."},{"title":"Cocina las bases","text":"Prepara el arroz integral y los platos principales la misma tarde."},{"title":"Porciona y congela","text":"Enfría, divide en recipientes, etiqueta con la fecha y congela."},{"title":"Varía (opcional)","text":"Incluye el bowl a la plancha y la salsa de hierbas para los días frescos."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Una tarde de preparación (unas 2 horas) por semana."},"needs":["Olla grande","Fuente para horno","Recipientes aptos para congelador","Etiquetas o cinta"],"care":"Recetas demostrativas. Alérgenos: el omelet lleva huevo y leche. Enfría antes de congelar, consume en un plazo de 30 días, descongela en la heladera y recalienta bien antes de comer."}$c$::jsonb),
  ('domingo-de-preparo', 'es', $c${"idea":"Una tarde de domingo bien organizada vale por toda la semana. Te guío para hacer arroz, omelet al horno y sopa la misma tarde, con mise en place para ganar tiempo — y empiezas el lunes con la heladera lista.","for_who":"Para quien tiene algunas horas libres el fin de semana y quiere adelantar las comidas de la semana de una vez.","not_for":"No es para quien no tiene tiempo ni espacio en el congelador para preparar en cantidad.","outcomes":["Arroz, omelet al horno y sopa listos la misma tarde","Un orden de preparación que aprovecha horno y hornalla al mismo tiempo","Porciones guardadas para la semana"],"method":[{"title":"Organiza antes","text":"Haz el mise en place: lava, corta y separa todo antes de encender el fuego."},{"title":"Horno y hornalla juntos","text":"Mete el omelet al horno mientras se cocinan el arroz integral y la sopa."},{"title":"Guarda","text":"Porciona, etiqueta y separa lo que va a la heladera y lo que va al congelador."}],"rhythm":{"sessions_per_week":1,"minutes_per_day":null,"note":"Una tarde de unas 2 horas y media por semana."},"needs":["Olla grande","Olla con tapa","Fuente para horno","Recipientes con tapa","Cuchillo de chef y tabla"],"care":"Recetas demostrativas. Alérgenos: el omelet lleva huevo y leche. Enfría antes de guardar, consume en pocos días lo que queda en la heladera y recalienta bien antes de comer."}$c$::jsonb);

update public.program_versions v set concept = s.concept
from seed_concept s
join public.programs p on p.slug = s.slug
where s.locale = 'pt-BR'
  and v.id = p.current_version_id
  and v.source_locale = 'pt-BR'
  and v.concept is null;

update public.program_localizations l set concept = s.concept
from seed_concept s
join public.programs p on p.slug = s.slug
where s.locale <> 'pt-BR'
  and l.version_id = p.current_version_id
  and l.locale = s.locale::public.locale_code
  and l.concept is null;

drop table if exists seed_concept;
